// Console 客户请求日志：只查当前用户、且账本 USD 净扣费大于 0 的请求。
// 不返回状态、渠道、服务商、平台成本、密钥明文或内部错误。
// 先过滤分页，再只对当前页 JOIN 展示字段。
func (q *Queries) ListConsoleBilledRequests(ctx context.Context, arg ListConsoleBilledRequestsParams) ([]ListConsoleBilledRequestsRow, error) {
	rows, err := q.db.Query(ctx, listConsoleBilledRequests,
		arg.SortField,
		arg.SortDesc,
		arg.UserID,
		arg.RouteIds,
		arg.ApiKeyIds,
		arg.Endpoints,
		arg.StreamTypes,
		arg.Q,
		arg.FromTime,
		arg.ToTime,
		arg.PageOffset,
		arg.PageLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListConsoleBilledRequestsRow
	for rows.Next() {
		var i ListConsoleBilledRequestsRow
		if err := rows.Scan(
			&i.TotalCount,
			&i.ID,
			&i.RequestID,
			&i.CreatedAt,
			&i.ClientIp,
			&i.RouteID,
			&i.RouteName,
			&i.ApiKeyID,
			&i.ApiKeyName,
			&i.ApiKeyPrefix,
			&i.ApiKeyPlaintext,
			&i.Endpoint,
			&i.Stream,
			&i.RequestedModelID,
			&i.ModelDisplayName,
			&i.IngressProtocol,
			&i.InputPricePer1m,
			&i.OutputPricePer1m,
			&i.CacheReadPricePer1m,
			&i.CacheWrite5mPricePer1m,
			&i.CacheWrite1hPricePer1m,
			&i.CacheWrite30mPricePer1m,
			&i.ReasoningOutputPricePer1m,
			&i.PriceServiceTier,
			&i.ReasoningEffort,
			&i.UncachedInputTokens,
			&i.CacheReadInputTokens,
			&i.CacheWrite5mInputTokens,
			&i.CacheWrite1hInputTokens,
			&i.CacheWrite30mInputTokens,
			&i.InputTokens,
			&i.OutputTokens,
			&i.ReasoningOutputTokens,
			&i.StartedAt,
			&i.CompletedAt,
			&i.GatewayFirstTokenAt,
			&i.UserChargeUsd,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

